function venueNames(city) {
  return (VENUE_TABLE[city] || []).map((v) => v.name);
}

function venueCoords(city, name) {
  return (VENUE_TABLE[city] || []).find((v) => v.name === name);
}

// Each venue gets its own short ID for organizer login — e.g. "AH-GMDC" —
// so logging in never requires browsing a list of every other venue.
function venueId(city, venue) {
  const cityPart = (city || "").replace(/[^A-Za-z]/g, "").slice(0, 2).toUpperCase();
  const venuePart = (venue || "").replace(/[^A-Za-z]/g, "").slice(0, 4).toUpperCase();
  return `${cityPart}-${venuePart}`;
}

function venueIdLookup() {
  const map = {};
  Object.keys(VENUE_TABLE).forEach((city) => {
    VENUE_TABLE[city].forEach((v) => {
      map[venueId(city, v.name)] = { city, venue: v.name };
    });
  });
  return map;
}

// Haversine distance in km — used only for a soft "you seem far away" nudge,
// never to block registration.
function distanceKm(lat1, lng1, lat2, lng2) {
  const R = 6371;
  const dLat = ((lat2 - lat1) * Math.PI) / 180;
  const dLng = ((lng2 - lng1) * Math.PI) / 180;
  const a =
    Math.sin(dLat / 2) ** 2 +
    Math.cos((lat1 * Math.PI) / 180) * Math.cos((lat2 * Math.PI) / 180) * Math.sin(dLng / 2) ** 2;
  return R * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
}

// Finds the closest known venue (across ALL cities) to a GPS position,
// Blinkit/Zomato-style — used to actively confirm the venue at the moment
// someone taps to register, rather than passively warning after the fact.
function findNearestVenue(lat, lng, thresholdKm = 2) {
  let best = null;
  for (const city of Object.keys(VENUE_TABLE)) {
    for (const v of VENUE_TABLE[city]) {
      const km = distanceKm(lat, lng, v.lat, v.lng);
      if (km <= thresholdKm && (!best || km < best.km)) {
        best = { city, venue: v.name, km };
      }
    }
  }
  return best;
}

// Event timing — default 7:30 PM start. Registration opens 6:30 PM, closes
// 1:30 AM (wraps past midnight). Circle chat auto-closes at 1:00 AM.
const REG_OPEN_MINUTES = 18 * 60 + 30; // 6:30 PM
const REG_CLOSE_MINUTES = 1 * 60 + 30; // 1:30 AM
const CHAT_CLOSE_MINUTES = 1 * 60; // 1:00 AM

function minutesOf(date) {
  return date.getHours() * 60 + date.getMinutes();
}

function isBeforeLiveSeason(now) {
  return now.toISOString().slice(0, 10) < LIVE_ENABLED_FROM;
}

function isWithinDailyWindow(now) {
  const m = minutesOf(now);
  return m >= REG_OPEN_MINUTES || m < REG_CLOSE_MINUTES;
}

function isRegistrationOpen(now) {
  return !isBeforeLiveSeason(now) && isWithinDailyWindow(now);
}

function isPastChatClose(now) {
  const m = minutesOf(now);
  return m >= CHAT_CLOSE_MINUTES && m < REG_OPEN_MINUTES;
}

// Dev-only: lets us test time-gated behaviour without waiting for the actual
// clock. Not part of the real product — purely a preview/testing aid.
function useDevClock() {
  const [override, setOverride] = useState(""); // "HH:mm"
  const [dateOverride, setDateOverride] = useState(""); // "YYYY-MM-DD"
  const getNow = () => {
    const d = dateOverride ? new Date(dateOverride + "T00:00:00") : new Date();
    if (override) {
      const [h, m] = override.split(":").map(Number);
      d.setHours(h, m, 0, 0);
    } else if (dateOverride) {
      const real = new Date();
      d.setHours(real.getHours(), real.getMinutes(), 0, 0);
    }
    return d;
  };
  return { override, setOverride, dateOverride, setDateOverride, getNow };
}

