const ALL_WOMEN_MIN_FLOOR = 4;
const SOFT_MAX_GROUP = 24;

function useGroupSimulator() {
  const [buckets, setBuckets] = useState({});
  function assign(key, gender, pref) {
    const bucketKey = `${key}:${pref}`;
    const prevState = buckets[bucketKey] || { groupIndex: 1, total: 0, male: 0, female: 0 };
    let startNew = prevState.total >= SOFT_MAX_GROUP;
    if (pref === "mixed") {
      const atCap = gender === "male" ? prevState.male >= GENDER_CAP : gender === "female" ? prevState.female >= GENDER_CAP : false;
      startNew = startNew || atCap;
    }
    let nextState = startNew
      ? { groupIndex: prevState.groupIndex + 1, total: 0, male: 0, female: 0 }
      : { ...prevState };
    nextState.total += 1;
    if (gender === "male") nextState.male += 1;
    if (gender === "female") nextState.female += 1;
    setBuckets((prev) => ({ ...prev, [bucketKey]: nextState }));
    return { groupIndex: nextState.groupIndex, currentSize: nextState.total };
  }
  return { assign };
}

// Festive backdrop: layered warm glows + a scattered dot/spark field, instead
// of a flat solid panel — meant to read as string-light/stage-glow ambience.
function FestiveBackdrop() {
  const sparks = [];
  let h = 7;
  for (let i = 0; i < 28; i++) {
    h = (h * 1103515245 + 12345) >>> 0;
    const x = h % 100;
    h = (h * 1103515245 + 12345) >>> 0;
    const y = h % 100;
    h = (h * 1103515245 + 12345) >>> 0;
    const c = ["#E3A542", "#DB2777", "#22C55E", "#00C2D1"][h % 4];
    sparks.push({ x, y, c, id: i });
  }
  return (
    <div style={{ position: "fixed", inset: 0, zIndex: 0, overflow: "hidden", pointerEvents: "none" }}>
      <div style={{ position: "absolute", top: "-10%", left: "-10%", width: "60%", height: "40%", background: "radial-gradient(circle, #DB277733 0%, transparent 70%)", filter: "blur(20px)" }} />
      <div style={{ position: "absolute", top: "10%", right: "-15%", width: "55%", height: "45%", background: "radial-gradient(circle, #E3A54233 0%, transparent 70%)", filter: "blur(20px)" }} />
      <div style={{ position: "absolute", bottom: "-10%", left: "20%", width: "60%", height: "35%", background: "radial-gradient(circle, #00C2D122 0%, transparent 70%)", filter: "blur(20px)" }} />
      {sparks.map((s) => (
        <div key={s.id} style={{ position: "absolute", left: s.x + "%", top: s.y + "%", width: 3, height: 3, borderRadius: "50%", background: s.c, opacity: 0.5 }} />
      ))}
    </div>
  );
}

