function FakeQrPattern({ seed }) {
  const cells = [];
  let h = 0;
  for (let i = 0; i < seed.length; i++) h = (h * 31 + seed.charCodeAt(i)) >>> 0;
  for (let i = 0; i < 121; i++) { h = (h * 1103515245 + 12345) >>> 0; cells.push(h % 3 === 0); }
  return (
    <div style={{ display: "grid", gridTemplateColumns: "repeat(11, 1fr)", gap: 2, width: 120, height: 120, background: "#F3EDE0", padding: 8, borderRadius: 10 }}>
      {cells.map((on, i) => <div key={i} style={{ background: on ? "#23213A" : "transparent" }} />)}
    </div>
  );
}

