function OrganizerDashboard({ onExit, history, pendingPools, showUpResponses }) {
  const [id, setId] = useState("");
  const [password, setPassword] = useState("");
  const [authed, setAuthed] = useState(false);
  const [error, setError] = useState("");
  const [resolved, setResolved] = useState(null); // { city, venue }

  // Mocked auth only — a real deployment issues each venue its own actual
  // ID and password, checked server-side. This just demonstrates the
  // "ID + password, no venue browsing" access model in a client-only preview.
  function expectedPassword(v) {
    return (v || "").toLowerCase().replace(/[^a-z]/g, "").slice(0, 4) + "2026";
  }

  function tryLogin() {
    setError("");
    const lookup = venueIdLookup();
    const match = lookup[id.toUpperCase().trim()];
    if (!match) { setError("Venue ID not recognized"); return; }
    if (password !== expectedPassword(match.venue)) { setError("Incorrect password"); return; }
    setResolved(match);
    setAuthed(true);
  }

  if (!authed) {
    return (
      <div style={{ maxWidth: 460, margin: "0 auto", width: "100%", position: "relative" }}>
        <FestiveBackdrop />
        <div style={{ padding: "16px 4vw 40px", position: "relative", zIndex: 1 }}>
          <GhostButton onClick={onExit}>← Exit</GhostButton>
          <h2 style={{ fontFamily: "'Baloo 2', cursive", fontSize: 22, color: "#F3EDE0", margin: "16px 0 6px" }}>📊 Organizer Dashboard</h2>
          <p style={{ fontFamily: "'Manrope', sans-serif", fontSize: 12.5, color: "#B9AFD1", marginBottom: 16 }}>
            Aggregate stats for your venue only — no attendee names, numbers, or payment amounts are shown here.
          </p>

          <Field label="Venue ID" required>
            <input style={{ ...inputStyle, textTransform: "uppercase" }} value={id} onChange={(e) => setId(e.target.value)} placeholder="e.g. AH-GMDC" />
          </Field>
          <Field label="Password" required error={error}>
            <input type="password" style={inputStyle} value={password} onChange={(e) => setPassword(e.target.value)} placeholder="Enter password" />
          </Field>

          <PrimaryButton onClick={tryLogin}>View Dashboard</PrimaryButton>

          <div style={{ fontFamily: "'Manrope', sans-serif", fontSize: 10, color: "#6E6590", textAlign: "center", marginTop: 12, lineHeight: 1.6 }}>
            Preview only — try Venue ID <strong>AH-GMDC</strong> with password <strong>gmdc2026</strong> (GMDC Ground, Ahmedabad).
            In production, each venue gets its own real ID and password issued by SoloSaathi.
          </div>
        </div>
      </div>
    );
  }

  const { city, venue } = resolved;

  const entries = (history || []).filter((h) => h.city === city && h.venue === venue);
  const advanceCount = entries.filter((e) => e.phase === "advance").length;
  const liveCount = entries.filter((e) => e.phase !== "advance").length;

  const pendingCount = Object.keys(pendingPools || {})
    .filter((k) => k.startsWith(`${city}:${venue}:`))
    .reduce((sum, k) => sum + (pendingPools[k]?.length || 0), 0);

  const levelCounts = { beginner: 0, intermediate: 0, advanced: 0 };
  entries.forEach((e) => { if (levelCounts[e.level] !== undefined) levelCounts[e.level]++; });

  const genderCounts = { male: 0, female: 0, unstated: 0 };
  entries.forEach((e) => { const g = e.gender || "unstated"; if (genderCounts[g] !== undefined) genderCounts[g]++; });

  const uniqueCircles = {};
  entries.forEach((e) => { uniqueCircles[e.circleId] = e; });
  const circleList = Object.values(uniqueCircles);
  const womenCircles = circleList.filter((c) => c.groupPreference === "women");
  const avgCircleSize = circleList.length ? (circleList.reduce((s, c) => s + c.memberCount, 0) / circleList.length).toFixed(1) : "—";
  const avgWomenCircleSize = womenCircles.length ? (womenCircles.reduce((s, c) => s + c.memberCount, 0) / womenCircles.length).toFixed(1) : "—";

  const showUpEntries = entries.filter((e) => showUpResponses[`${e.mobile}:${e.circleId}`]);
  const showUpYes = showUpEntries.filter((e) => showUpResponses[`${e.mobile}:${e.circleId}`] === "yes").length;
  const showUpRate = showUpEntries.length ? Math.round((showUpYes / showUpEntries.length) * 100) + "%" : "No data yet";

  const total = entries.length;
  const pct = (n) => (total ? Math.round((n / total) * 100) : 0);

  return (
    <div style={{ maxWidth: 460, margin: "0 auto", width: "100%", position: "relative" }}>
      <FestiveBackdrop />
      <div style={{ padding: "16px 4vw 40px", position: "relative", zIndex: 1 }}>
        <GhostButton onClick={onExit}>← Exit</GhostButton>
        <h2 style={{ fontFamily: "'Baloo 2', cursive", fontSize: 22, color: "#F3EDE0", margin: "16px 0 4px" }}>📊 {venue}</h2>
        <p style={{ fontFamily: "'Manrope', sans-serif", fontSize: 12, color: "#8A81A8", marginBottom: 16 }}>{city} · Aggregate stats only</p>

        <Row2>
          <SectionCard style={{ flex: 1, textAlign: "center" }}>
            <div style={{ fontFamily: "'Baloo 2', cursive", fontSize: 26, color: "#E3A542" }}>{total}</div>
            <div style={{ fontFamily: "'Manrope', sans-serif", fontSize: 10.5, color: "#8A81A8" }}>Total registrations</div>
          </SectionCard>
          <SectionCard style={{ flex: 1, textAlign: "center" }}>
            <div style={{ fontFamily: "'Baloo 2', cursive", fontSize: 26, color: "#7C3AED" }}>{pendingCount}</div>
            <div style={{ fontFamily: "'Manrope', sans-serif", fontSize: 10.5, color: "#8A81A8" }}>Pending (advance)</div>
          </SectionCard>
        </Row2>

        <div style={{ height: 12 }} />

        <SectionCard style={{ marginBottom: 12 }}>
          <div style={{ fontFamily: "'Manrope', sans-serif", fontSize: 11, fontWeight: 700, color: "#B29CE0", marginBottom: 8, textTransform: "uppercase" }}>Registration source</div>
          <div style={{ display: "flex", justifyContent: "space-between", fontFamily: "'Manrope', sans-serif", fontSize: 12.5, color: "#F3EDE0", marginBottom: 4 }}>
            <span>📅 Advance</span><span>{advanceCount} ({pct(advanceCount)}%)</span>
          </div>
          <div style={{ display: "flex", justifyContent: "space-between", fontFamily: "'Manrope', sans-serif", fontSize: 12.5, color: "#F3EDE0" }}>
            <span>🔍 Live walk-in</span><span>{liveCount} ({pct(liveCount)}%)</span>
          </div>
        </SectionCard>

        <SectionCard style={{ marginBottom: 12 }}>
          <div style={{ fontFamily: "'Manrope', sans-serif", fontSize: 11, fontWeight: 700, color: "#B29CE0", marginBottom: 8, textTransform: "uppercase" }}>Skill level breakdown</div>
          {LEVELS.map((l) => (
            <div key={l.id} style={{ display: "flex", justifyContent: "space-between", fontFamily: "'Manrope', sans-serif", fontSize: 12.5, color: "#F3EDE0", marginBottom: 4 }}>
              <span>{l.icon} {l.label}</span><span>{levelCounts[l.id]} ({pct(levelCounts[l.id])}%)</span>
            </div>
          ))}
        </SectionCard>

        <SectionCard style={{ marginBottom: 12 }}>
          <div style={{ fontFamily: "'Manrope', sans-serif", fontSize: 11, fontWeight: 700, color: "#B29CE0", marginBottom: 8, textTransform: "uppercase" }}>Gender balance (aggregate)</div>
          <div style={{ display: "flex", justifyContent: "space-between", fontFamily: "'Manrope', sans-serif", fontSize: 12.5, color: "#F3EDE0", marginBottom: 4 }}><span>Male</span><span>{pct(genderCounts.male)}%</span></div>
          <div style={{ display: "flex", justifyContent: "space-between", fontFamily: "'Manrope', sans-serif", fontSize: 12.5, color: "#F3EDE0", marginBottom: 4 }}><span>Female</span><span>{pct(genderCounts.female)}%</span></div>
          <div style={{ display: "flex", justifyContent: "space-between", fontFamily: "'Manrope', sans-serif", fontSize: 12.5, color: "#F3EDE0" }}><span>Prefer not to say</span><span>{pct(genderCounts.unstated)}%</span></div>
        </SectionCard>

        <SectionCard style={{ marginBottom: 12 }}>
          <div style={{ fontFamily: "'Manrope', sans-serif", fontSize: 11, fontWeight: 700, color: "#B29CE0", marginBottom: 8, textTransform: "uppercase" }}>Circles formed</div>
          <div style={{ display: "flex", justifyContent: "space-between", fontFamily: "'Manrope', sans-serif", fontSize: 12.5, color: "#F3EDE0", marginBottom: 4 }}><span>Total circles</span><span>{circleList.length}</span></div>
          <div style={{ display: "flex", justifyContent: "space-between", fontFamily: "'Manrope', sans-serif", fontSize: 12.5, color: "#F3EDE0", marginBottom: 4 }}><span>Average size</span><span>{avgCircleSize}</span></div>
          <div style={{ display: "flex", justifyContent: "space-between", fontFamily: "'Manrope', sans-serif", fontSize: 12.5, color: "#F3EDE0", marginBottom: 4 }}><span>🛡️ All-women circles</span><span>{womenCircles.length}</span></div>
          <div style={{ display: "flex", justifyContent: "space-between", fontFamily: "'Manrope', sans-serif", fontSize: 12.5, color: "#F3EDE0" }}><span>Avg all-women size</span><span>{avgWomenCircleSize}</span></div>
        </SectionCard>

        <SectionCard>
          <div style={{ fontFamily: "'Manrope', sans-serif", fontSize: 11, fontWeight: 700, color: "#B29CE0", marginBottom: 8, textTransform: "uppercase" }}>Show-up rate</div>
          <div style={{ fontFamily: "'Baloo 2', cursive", fontSize: 22, color: "#3EE07A" }}>{showUpRate}</div>
          <div style={{ fontFamily: "'Manrope', sans-serif", fontSize: 10.5, color: "#8A81A8", marginTop: 4 }}>Based on {showUpEntries.length} post-event responses so far</div>
        </SectionCard>
      </div>
    </div>
  );
}

