export default function App() {
  const [view, setView] = useState("home");
  const sim = useGroupSimulator();
  const [history, setHistory] = useState([]); // past registrations across days, per WhatsApp number
  const [showUpResponses, setShowUpResponses] = useState({}); // `${mobile}:${circleId}` -> "yes" | "no"
  const [devDay, setDevDay] = useState("Today");
  const devClock = useDevClock();

  // Advance Registration lifecycle — simulated stages standing in for what a
  // real backend would drive off actual calendar dates and a scheduled job.
  const STAGES = ["advance-open", "deadline-48h", "day-before", "day-of", "pre-live-2hr", "live", "post-event"];
  const [eventStage, setEventStage] = useState("advance-open");
  const stageIndex = STAGES.indexOf(eventStage);
  const isAdvanceRegOpen = stageIndex < STAGES.indexOf("pre-live-2hr");
  const isPreLiveChatUnlocked = stageIndex >= STAGES.indexOf("pre-live-2hr");
  const showDayBefore = stageIndex >= STAGES.indexOf("day-before");
  const showDayOf = stageIndex >= STAGES.indexOf("day-of");
  const showPostEvent = eventStage === "post-event";

  const [pendingPools, setPendingPools] = useState({}); // bucketKey -> [entries]

  function pendingBucketKey(city, venue, level, pref, eventDate) {
    return `${city}:${venue}:${level}:${pref}:${eventDate}`;
  }

  function addPendingRegistrant(bucketKey, profile) {
    setPendingPools((p) => ({ ...p, [bucketKey]: [...(p[bucketKey] || []), profile] }));
  }

  function addMockPendingRegistrants(bucketKey, count, level) {
    const mocks = MOCK_NAMES.slice(0, count).map((n) => ({ name: n, whatsapp: null, gender: "unstated", iceBreaker: false, level, isMock: true }));
    setPendingPools((p) => ({ ...p, [bucketKey]: [...(p[bucketKey] || []), ...mocks] }));
  }

  function finalizeBucket(bucketKey) {
    const entries = pendingPools[bucketKey] || [];
    if (entries.length === 0) return null;
    const [city, venue, level, pref, eventDate] = bucketKey.split(":");
    const groupIndex = Math.floor(Math.random() * 90) + 1;
    const prefix = pref === "women" ? "SAKHI" : level === "advanced" ? "RAAS" : level === "intermediate" ? "TAAL" : "GARBA";
    const circleId = `${prefix}-${String(groupIndex).padStart(2, "0")}`;
    const landmark = LANDMARKS[groupIndex % LANDMARKS.length];
    const zone = ZONES[groupIndex % ZONES.length];
    const captainEntry = entries.find((e) => e.iceBreaker) || entries[0];
    const roster = entries.map((e) => ({ name: e.name, tag: e === captainEntry ? "CAPTAIN" : null, level: LEVELS.find((l) => l.id === level)?.label || level }));

    // One real-person history entry per actual registrant (not the mock fillers).
    entries.filter((e) => e.whatsapp).forEach((e) => {
      const token = `SOLO-PASS-${Date.now().toString(36).toUpperCase()}-${circleId}-${e.name.slice(0, 2)}`;
      setHistory((h) => [...h, {
        mobile: e.whatsapp, circleId, landmark, zone, token, level, memberCount: entries.length, roster,
        groupPreference: pref, phase: "advance", dayLabel: "Advance Registration", isToday: false, city, venue, gender: e.gender,
      }]);
    });

    setPendingPools((p) => ({ ...p, [bucketKey]: [] }));
    return { circleId, memberCount: entries.length };
  }

  function addHistory(record) {
    setHistory((h) => {
      const idx = h.findIndex((e) => e.mobile === record.mobile && e.dayLabel === devDay && e.phase !== "advance");
      const entry = { ...record, dayLabel: devDay, isToday: devDay === "Today", phase: "live" };
      if (idx >= 0) {
        const copy = [...h];
        copy[idx] = entry;
        return copy;
      }
      return [...h, entry];
    });
  }

  return (
    <div style={{ minHeight: "100vh", background: "radial-gradient(ellipse at top, #241D42, #14101F 70%)", fontFamily: "'Manrope', sans-serif", width: "100%", overflowX: "hidden", position: "relative" }}>
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Baloo+2:wght@500;700&family=Manrope:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500&display=swap');
        * { box-sizing: border-box; }
        html, body { max-width: 100%; overflow-x: hidden; }
        input::placeholder, textarea::placeholder { color: #6E6590; }
        select option { background: #241D3D; }
      `}</style>

      <div style={{ position: "relative", zIndex: 1, background: "#E3A54222", borderBottom: "0.5px solid #E3A54255", padding: "6px 4vw", display: "flex", flexWrap: "wrap", justifyContent: "center", alignItems: "center", gap: 8, fontFamily: "'Manrope', sans-serif", fontSize: 10.5, color: "#E3A542" }}>
        <span>Preview build — no backend or deployment.</span>
        <span style={{ opacity: 0.7 }}>|</span>
        <span>Simulate time:</span>
        <select
          value={devClock.override}
          onChange={(e) => devClock.setOverride(e.target.value)}
          style={{ background: "#241D3D", color: "#E3A542", border: "0.5px solid #E3A54255", borderRadius: 6, fontSize: 10, padding: "2px 4px" }}
        >
          <option value="">Real time ({new Date().toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" })})</option>
          <option value="16:00">4:00 PM (before window)</option>
          <option value="20:00">8:00 PM (open)</option>
          <option value="00:45">12:45 AM (near close, still open)</option>
          <option value="01:15">1:15 AM (past close)</option>
          <option value="02:00">2:00 AM (closed)</option>
        </select>
        <span style={{ opacity: 0.7 }}>|</span>
        <span>Simulate date:</span>
        <select
          value={devClock.dateOverride}
          onChange={(e) => devClock.setDateOverride(e.target.value)}
          style={{ background: "#241D3D", color: "#E3A542", border: "0.5px solid #E3A54255", borderRadius: 6, fontSize: 10, padding: "2px 4px" }}
        >
          <option value="">Real date ({new Date().toLocaleDateString()})</option>
          <option value="2026-10-12">Oct 12, 2026 (before live opens)</option>
          <option value="2026-10-13">Oct 13, 2026 (live opens)</option>
          <option value="2026-10-20">Oct 20, 2026 (mid-event)</option>
        </select>
        <span style={{ opacity: 0.7 }}>|</span>
        <span>Simulate day (testing history):</span>
        <select
          value={devDay}
          onChange={(e) => setDevDay(e.target.value)}
          style={{ background: "#241D3D", color: "#E3A542", border: "0.5px solid #E3A54255", borderRadius: 6, fontSize: 10, padding: "2px 4px" }}
        >
          <option value="Today">Today — new registrations count as tonight</option>
          <option value="Yesterday">Yesterday</option>
          <option value="2 nights ago">2 nights ago</option>
        </select>
        <span style={{ opacity: 0.7 }}>|</span>
        <span>Simulate event stage:</span>
        <select
          value={eventStage}
          onChange={(e) => setEventStage(e.target.value)}
          style={{ background: "#241D3D", color: "#E3A542", border: "0.5px solid #E3A54255", borderRadius: 6, fontSize: 10, padding: "2px 4px" }}
        >
          <option value="advance-open">Advance registration open</option>
          <option value="deadline-48h">48h before event (rolling finalize, reg. still open)</option>
          <option value="day-before">Day-before reminder</option>
          <option value="day-of">Day-of reminder</option>
          <option value="pre-live-2hr">1-2h before — pre-live chat unlocks</option>
          <option value="live">Live tonight</option>
          <option value="post-event">Post-event (show/no-show)</option>
        </select>
      </div>

      {view === "home" && (
        <div style={{ width: "100%", position: "relative" }}>
          <FestiveBackdrop />
          <nav style={{ position: "relative", zIndex: 1, display: "flex", flexWrap: "wrap", justifyContent: "space-between", alignItems: "center", gap: 8, padding: "14px 4vw", maxWidth: 460, margin: "0 auto" }}>
            <img src={LOGO_IMG} alt={BRAND} style={{ height: 40, maxWidth: "60vw" }} />
            <div style={{ display: "flex", gap: 6, flexWrap: "wrap" }}>
              <GhostButton onClick={() => setView("find")}>Find Circle</GhostButton>
              <GhostButton onClick={() => setView("notifications")}>🔔</GhostButton>
              <GhostButton onClick={() => setView("partner")}>Venues</GhostButton>
              <GhostButton onClick={() => setView("organizer")}>📊 Organizer</GhostButton>
            </div>
          </nav>

          <div style={{ position: "relative", zIndex: 1, maxWidth: 460, margin: "0 auto", padding: "8px 4vw 30px", textAlign: "center" }}>
            <Badge color="#E3A542">💃 For solo Garba dancers</Badge>
            <h1 style={{ fontFamily: "'Baloo 2', cursive", fontSize: "clamp(26px, 7vw, 32px)", lineHeight: 1.2, color: "#F3EDE0", margin: "14px 0 10px" }}>
              You came to dance.<br />
              <span style={{ background: "linear-gradient(90deg,#F5B301,#DB2777)", WebkitBackgroundClip: "text", WebkitTextFillColor: "transparent" }}>Not to stand alone.</span>
            </h1>
            <p style={{ fontSize: 13, color: "#B9AFD1", margin: "0 0 20px", lineHeight: 1.6 }}>
              Register, pick your level, and get placed in an evenly matched circle — with a Captain leading the first round.
            </p>
            <PrimaryButton onClick={() => setView("register")} style={{ fontSize: 15, padding: "15px 28px", width: "auto", marginBottom: 10 }}>🔍 Find Solo Garba Circle</PrimaryButton>
            <div>
              <GhostButton onClick={() => setView("advance")} style={{ padding: "10px 18px" }}>
                💃 Pre-Book My Circle
              </GhostButton>
            </div>
          </div>

          <div style={{ position: "relative", zIndex: 1, maxWidth: 460, margin: "0 auto", padding: "0 4vw 40px" }}>
            <div style={{ display: "flex", flexWrap: "wrap", gap: 8 }}>
              {LEVELS.map((l) => (
                <div key={l.id} style={{ flex: "1 1 90px", padding: 14, borderRadius: 12, background: `linear-gradient(160deg, ${l.bg}, #1F1938)`, border: `0.5px solid ${l.color}55`, textAlign: "center", boxShadow: `0 4px 18px -6px ${l.color}55` }}>
                  <div style={{ fontSize: 18, marginBottom: 4 }}>{l.icon}</div>
                  <div style={{ fontFamily: "'Manrope', sans-serif", fontWeight: 700, fontSize: 11.5, color: "#F3EDE0" }}>{l.label}</div>
                </div>
              ))}
            </div>
          </div>

          <footer style={{ position: "relative", zIndex: 1, borderTop: "0.5px solid #3A3257", padding: "20px 4vw", textAlign: "center" }}>
            <div style={{ display: "inline-block", background: "#FFFFFF", borderRadius: 8, padding: "6px 12px", marginBottom: 10 }}>
              <img src={KRITZ_IMG} alt="Kritz Vyonera AI Studio" style={{ height: 22, display: "block" }} />
            </div>
            <div style={{ fontFamily: "'Manrope', sans-serif", fontSize: 10.5, color: "#8A81A8" }}>
              {BRAND} is produced by Kritz Vyonera AI Studio.
            </div>
          </footer>
        </div>
      )}

      {view === "register" && <RegistrationFlow onExit={() => setView("home")} sim={sim} addHistory={addHistory} getNow={devClock.getNow} />}
      {view === "find" && <FindCircleFlow onExit={() => setView("home")} history={history} getNow={devClock.getNow} isPreLiveChatUnlocked={isPreLiveChatUnlocked} />}
      {view === "partner" && <PartnerPage onExit={() => setView("home")} />}
      {view === "advance" && (
        <AdvanceRegistrationFlow
          onExit={() => setView("home")}
          isAdvanceRegOpen={isAdvanceRegOpen}
          pendingBucketKey={pendingBucketKey}
          addPendingRegistrant={addPendingRegistrant}
          addMockPendingRegistrants={addMockPendingRegistrants}
          finalizeBucket={finalizeBucket}
          pendingPools={pendingPools}
        />
      )}
      {view === "notifications" && (
        <NotificationsView
          onExit={() => setView("home")}
          history={history}
          showDayBefore={showDayBefore}
          showDayOf={showDayOf}
          showPostEvent={showPostEvent}
          showUpResponses={showUpResponses}
          setShowUpResponses={setShowUpResponses}
        />
      )}
      {view === "organizer" && (
        <OrganizerDashboard onExit={() => setView("home")} history={history} pendingPools={pendingPools} showUpResponses={showUpResponses} />
      )}
    </div>
  );
}
